 for(const char* name:{"KHR_materials_clearcoat","KHR_materials_transmission","KHR_materials_volume","KHR_materials_ior","KHR_materials_specular"}){auto f=base;f.extra=",\"extensionsUsed\":["+Quoted(name)+"],\"extensionsRequired\":["+Quoted(name)+"]";f.materials={"{\"extensions\":{"+Quoted(name)+":{}}}"};s.Accept(name,f,{name,"Baseline metallic-roughness fallback","no clearcoat or refraction"});}
