 auto triangles=base;std::vector<uint16_t> index(90000);for(size_t i=0;i<index.size();++i)index[i]=uint16_t(i%3);auto first=triangles.AddU16(index,"SCALAR",index.size());index.resize(90003);for(size_t i=90000;i<index.size();++i)index[i]=uint16_t(i%3);auto second=triangles.AddU16(index,"SCALAR",index.size());triangles.primitives={"{\"attributes\":{\"POSITION\":0},\"indices\":"+std::to_string(first)+"}","{\"attributes\":{\"POSITION\":0},\"indices\":"+std::to_string(second)+"}"};s.Reject("triangle-budget",triangles,{"60001 triangles","maximum 60000"});
