 auto skinMorph=Skin();auto skinDelta=skinMorph.Add({0,0,.2f,0,0,.4f,0,0,.6f},"VEC3",3);auto close=skinMorph.primitives[0].rfind('}');skinMorph.primitives[0].insert(close,",\"targets\":[{\"POSITION\":"+std::to_string(skinDelta)+"}]");skinMorph.nodes[0]="{\"mesh\":0,\"skin\":0,\"translation\":[100,200,300],\"weights\":[0.5]}";auto composed=s.Accept("skin-morph-composition",skinMorph,{"Rest-pose joint skin baked","Authored default morph weights baked"});WorldVertex(composed,0,{0,.75f,.1f});WorldVertex(composed,2,{0,3.25f,.3f});
