int wmain(int argc,wchar_t** argv){try{if(argc==4&&std::wstring(argv[1])==L"--probe"){R::LocalFaceFilterImportResult result;std::string error;bool ok=R::ImportLocalFaceFilter(argv[2],argv[3],result,error);std::cout<<"{\"success\":"<<(ok?"true":"false")<<",\"error\":"<<Quoted(error)<<",\"notice\":"<<Quoted(result.notice)<<",\"sourceSha256\":"<<Quoted(result.sourceSha256)<<",\"nativePath\":"<<Quoted(fs::path(result.nativePath).u8string())<<",\"vertices\":"<<(result.model?result.model->vertices.size():0)<<",\"triangles\":"<<(result.model?result.model->triangles.size():0)<<"}\n";return ok?0:2;}
 Need(argc==2,"usage: local-import-diagnostics.exe <absolute-fixture-folder> or --probe <glb> <absolute-library>");Need(fs::path(argv[1]).is_absolute(),"absolute fixture path");Suite suite(argv[1]);Diagnostics(suite);RestAnimation(suite);RestSkin(suite);RestMorph(suite);std::cout<<"LOCAL_IMPORT_DIAGNOSTICS groups="<<groups<<" assertions="<<checks<<" PASS\n";return 0;}catch(const std::exception& e){std::cerr<<"LOCAL_IMPORT_DIAGNOSTICS FAIL after "<<checks<<" assertions: "<<e.what()<<"\n";return 1;}}
